export const APPROVED_VISUAL_IDS = Object.freeze(Object.keys(VISUAL_REGISTRY));

export function getVisualDefinition(visualId) {
  return VISUAL_REGISTRY[visualId] || null;
}

export function isApprovedVisualId(visualId) {
  return Boolean(getVisualDefinition(visualId));
}
